def range_compress(arr):
    if not arr:
        return []
    uniq = sorted(set(arr))
    res = []
    i = 0
    while i < len(uniq):
        start = uniq[i]
        j = i + 1
        while j < len(uniq) and uniq[j] == uniq[j-1] + 1:
            j += 1
        end = uniq[j-1]
        if start == end:
            res.append([start])
        else:
            res.append([start, end])
        i = j
    return res
